type TreeNode = { v: number; L: TreeNode | null; R: TreeNode | null };
// Level-order array, null for a missing child.
function buildTree(values: (number | null)[]): TreeNode | null {
  if (!values.length || values[0] == null) return null;
  const root: TreeNode = { v: values[0], L: null, R: null };
  const q = [root];
  let i = 1;
  while (q.length && i < values.length) {
    const cur = q.shift()!;
    const l = values[i++];
    if (l != null) { cur.L = { v: l, L: null, R: null }; q.push(cur.L); }
    const r = values[i++];
    if (r != null) { cur.R = { v: r, L: null, R: null }; q.push(cur.R); }
  }
  return root;
}

function save(root: TreeNode | null): string {
  const out: string[] = [];
  const walk = (n: TreeNode | null): void => {
    if (!n) { out.push("#"); return; }
    out.push(String(n.v));
    walk(n.L);
    walk(n.R);
  };
  walk(root);
  return out.join(",");
}

function restore(text: string): TreeNode | null {
  const tokens = text.split(",");
  let i = 0;
  const build = (): TreeNode | null => {
    const t = tokens[i++];
    if (t === "#" || t === undefined || t === "") return null;
    const n: TreeNode = { v: Number(t), L: null, R: null };
    n.L = build();
    n.R = build();
    return n;
  };
  return build();
}

function toLevelOrder(root: TreeNode | null): (number | null)[] {
  const out: (number | null)[] = [];
  const q: (TreeNode | null)[] = [root];
  for (let i = 0; i < q.length; i++) {
    const n = q[i];
    out.push(n ? n.v : null);
    if (n) q.push(n.L, n.R);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return out;
}
function roundTrip(values: (number | null)[]): (number | null)[] | string {
  const root = buildTree(values);
  const text = save(root);
  if (typeof text !== "string") return "save must return a string";
  const wipe = (n: TreeNode | null): void => { if (n) { n.v = NaN; wipe(n.L); wipe(n.R); } };
  wipe(root);
  return toLevelOrder(restore(text));
}
